<?php
use App\Http\Controllers\Auth\LoginController; use App\Http\Controllers\BusController; use App\Http\Controllers\HomeController; use App\Http\Controllers\SearchController; use App\Http\Controllers\Admin; use Illuminate\Support\Facades\Route;
Route::get('/',HomeController::class)->name('home'); Route::get('/cari-rute',SearchController::class)->name('search'); Route::get('/bus/{bus}',[BusController::class,'show'])->name('buses.show');
Route::middleware('guest')->group(function(){Route::get('/login',[LoginController::class,'create'])->name('login');Route::post('/login',[LoginController::class,'store'])->name('login.store');}); Route::post('/logout',[LoginController::class,'destroy'])->middleware('auth')->name('logout');
Route::prefix('admin')->name('admin.')->middleware(['auth','admin'])->group(function(){Route::resource('buses',Admin\BusController::class);Route::resource('stops',Admin\StopController::class);Route::resource('routes',Admin\RouteController::class);Route::resource('schedules',Admin\ScheduleController::class);});
